import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

public class ConcurrentHashMapDemo {
    public static void main(String[] args) {
        ConcurrentMap<String, String> cache = new ConcurrentHashMap<>();

        // Atomic conditional put (CAS-based under the hood in Java 8)
        cache.putIfAbsent("databaseUrl", "jdbc:mysql://localhost:3306/prod");

        // Thread-safe atomic compute operation without explicit external locking
        cache.computeIfPresent("databaseUrl", (key, oldValue) -> {
            return oldValue + "?useSSL=true";
        });

        System.out.println(cache.get("databaseUrl"));
    }
}
